// Synthetic key-terms sheet in the layout of a Georgian bank card "მნიშვნელოვანი პირობები" document (values invented).
import PDFDocument from 'pdfkit';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const FONT = path.join(path.dirname(fileURLToPath(import.meta.url)), 'NotoSansGeorgian-Regular.ttf');
const L: [number, string][][] = [
  [[40, 'მიმდინარე მნიშვნელოვანი პირობები']],
  [[40, 'ტოპ ქარდის ბარათის საპროცენტო განაკვეთის ტიპი:'], [300, 'ფიქსირებული საპროცენტო განაკვეთი']],
  [[40, 'ტოპ ქარდის წლიური საპროცენტო განაკვეთი:'], [300, 'ტოპ ქარდის წლიური საპროცენტო განაკვეთი უნაღდო']],
  [[300, 'ანგარიშსწორებისას - რეკომენდებული გადასახად(ებ)ის გადახდის']], [[300, 'შემთხვევაში - 0 %;']],
  [[300, 'მინიმალური გადასახად(ებ)ის გადახდის შემთხვევაში -']], [[300, '30.00 %;']],
  [[40, 'ტოპ ქარდის ეფექტური საპროცენტო განაკვეთი:'], [300, 'უნაღდო ანგარიშსწორებისას რეკომენდებული']],
  [[300, 'გადასახად(ებ)ის გადახდის შემთხვევაში - 0.00 %;']],
  [[300, 'მინიმალური გადასახად(ებ)ის გადახდის შემთხვევაში - 28.10 %;']],
  [[40, 'ტოპ ქარდის მაქსიმალური ეფექტური საპროცენტო განაკვეთი - 50.00%;']],
  [[40, 'ყოველთვიური შენატანის ოდენობა:'], [300, 'მინიმალური გადასახადი - 55.10 ლარი. რეკომენდებული']],
  [[40, 'თანხის ბანკის ბანკომატში განაღდების საკომისიო:'], [300, '2.5%, მინიმუმ 5 (ხუთი) ლარი']],
  [[40, 'ტოპ ქარდი განვადების ლიმიტი:'], [300, '2000 ლარი']],
  [[40, 'ტოპ ქარდის ხელშეკრულების მოქმედების ვადა:'], [300, '01/02/2070, მაგრამ ყველა შემთხვევაში']],
  [[40, 'პირგასამტეხლო ვადის გადაცილებისათვის:'], [300, 'ერთჯერადად 8.00 ლარი ვადაგადაცილების პირველ დღეს']],
  [[300, 'ვადაგადაცილებული თანხის 0.40 % ყოველ ვადაგადაცილებულ დღეზე']],
];
export function termsPdf(): Promise<Uint8Array> {
  return new Promise((res) => {
    const d = new PDFDocument({ size: 'A4', margin: 20 }); const bufs: Buffer[] = [];
    d.on('data', (b) => bufs.push(b)); d.on('end', () => res(new Uint8Array(Buffer.concat(bufs))));
    d.font(FONT).fontSize(7); let y = 30;
    for (const row of L) { row.forEach(([x, s]) => d.text(s, x, y, { lineBreak: false })); y += 13; }
    d.end();
  });
}
